llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C50"],
      "claim": "Sotalol, a structurally related beta-amino alcohol arylsulfonamide, has an absolute oral bioavailability of 90-100% in humans, strongly supporting high F for the query's similar beta-hydroxyethylamine motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Metoprolol, another beta-amino alcohol aryl ether, has an absolute oral bioavailability of 38-60% in humans, all above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Atazanavir, a larger polar drug with multiple amide-like features, has an oral bioavailability of 68% (57-80%) in humans, supporting high F despite substantial polarity and molecular complexity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Vorinostat, an anilide hydroxamic acid with amide and aromatic groups, has an absolute oral bioavailability of approximately 43% in humans, supporting high F for the query's amide-containing structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Labetalol, a beta-blocker with an amide and phenolic groups, has a systemic bioavailability of 26% after oral dosing, still above the 20% threshold, supporting high F at this endpoint.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability at or above 20%, mostly in the 38-100% range, and no affirmative evidence supports F<20%; therefore the query is predicted to have high oral bioavailability at the F>=20% threshold.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement exists for the query molecule.",
    "The query's aminothiazole and amide linker may introduce metabolic or permeability liabilities not fully captured by the beta-blocker analogues.",
    "Some analogues such as labetalol are near the lower boundary of the >=20% range, so the exact F could be close to the threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

